mapper.select:
select a.apply_id, a.apply_no, a.member_id, a.apply_type, a.amount, a.fee, a.actual_amount, a.status,
       a.account_name, a.account_no, a.bank_name, a.remark, a.audit_by, a.audit_time, a.audit_remark,
       a.create_time, m.nickname as member_name, m.phone as member_phone, m.balance as member_balance
from hys_fund_apply a
left join hys_member m on m.member_id = a.member_id

    and a.member_id = #{memberId}
    and a.apply_type = #{applyType}
    and a.status = #{status}
    and a.apply_no like concat('%', #{applyNo}, '%')

order by a.apply_id desc
